      C("We're considering ___ to Canada.", ["moving", "to move", "move"], "moving", "Consider + -ing.", tp="gerund"),
      C("She's good at ___ .", ["drawing", "to draw", "draw"], "drawing", "Після прийменника — -ing.", "После предлога — -ing.", tp="gerund"),
