      W(["to call", "calling"], ["He promised ___ me.", "He kept ___ me.", "I suggest ___ her.", "She refused ___ him."], ["to call", "calling", "calling", "to call"], "promise / refuse + to; keep / suggest + -ing.", tp="gerund-vs-infinitive"),
