# ============ 14. Косвенная речь: основы ============
UNITS.append(unit(14, "grammar", "Reported speech: basics", "Непряма мова: основи", "Косвенная речь: основы",
  rule(("He said (that)… — час «зсувається» на крок у минуле: is → was, will → would, can → could", "He said (that)… — время «сдвигается» на шаг в прошлое: is → was, will → would, can → could"),
       "Переказуємо чужі слова: «I'm tired» → She said (that) she was tired. Займенники теж змінюються: I → she, my → her.",
       "Пересказываем чужие слова: «I'm tired» → She said (that) she was tired. Местоимения тоже меняются: I → she, my → her.",
       [("'I'm busy.' → He said he was busy.", "«Я зайнятий» → Він сказав, що зайнятий.", "«Я занят» → Он сказал, что занят."),
        ("'I'll call you.' → She said she would call me.", "«Я тобі подзвоню» → Вона сказала, що подзвонить.", "«Я тебе позвоню» → Она сказала, что позвонит."),
        ("'I can swim.' → He told me he could swim.", "«Я вмію плавати» → Він сказав, що вміє плавати.", "«Я умею плавать» → Он сказал, что умеет плавать.")],
       ("В українській час не змінюється: «сказав, що втомлений». В англійській після said — крок назад: said he was tired.",
        "В русском время не меняется: «сказал, что устал». В английском после said — шаг назад: said he was tired.")),
  [V("say → said", "/sed/", "казати → сказав", "говорить → сказал", "She said she was tired."),
   V("tell → told", "/təʊld/", "казати (комусь) → сказав", "говорить (кому-то) → сказал", "He told me he was busy."),
   V("explain", "/ɪkˈspleɪn/", "пояснювати", "объяснять", "She explained that…"),
   V("mention", "/ˈmenʃn/", "згадувати", "упоминать", "He mentioned that…"),
   V("reply", "/rɪˈplaɪ/", "відповідати", "отвечать", "She replied that…"),
   V("that", "/ðæt/", "що (сполучник)", "что (союз)", "He said that…"),
   V("the day before", "/ðə deɪ bɪˈfɔː/", "напередодні", "накануне", "yesterday → the day before"),
   V("the next day", "/ðə nekst deɪ/", "наступного дня", "на следующий день", "tomorrow → the next day"),
   V("then", "/ðen/", "тоді", "тогда", "now → then"),
   V("there", "/ðeə/", "там", "там", "here → there"),
   V("gossip", "/ˈɡɒsɪp/", "плітки", "сплетни", "Have you heard the gossip?")],
  [
   lesson("Statements", "Твердження", "Утверждения",
     rule(("She said (that) + речення з займенником, зміненим на «її / його»", "She said (that) + предложение с местоимением, изменённым на «её / его»"),
          "That можна пропустити: He said (that) he liked it. Займенники — з погляду того, хто переказує: «I love my job» → She said she loved her job.",
          "That можно опустить: He said (that) he liked it. Местоимения — с точки зрения того, кто пересказывает: «I love my job» → She said she loved her job.",
          [("'I like pizza.' → He said he liked pizza.", "«Я люблю піцу» → Він сказав, що любить піцу.", "«Я люблю пиццу» → Он сказал, что любит пиццу."),
           ("'I'm hungry.' → She said she was hungry.", "«Я голодна» → Вона сказала, що голодна.", "«Я голодна» → Она сказала, что голодна."),
           ("'We live in Kyiv.' → They said they lived in Kyiv.", "«Ми живемо в Києві» → Вони сказали, що живуть у Києві.", "«Мы живём в Киеве» → Они сказали, что живут в Киеве.")]),
     [C("'I'm tired.' → She said she ___ tired.", ["was", "is", "were"], "was", "Is → was.", tp="reported-statements"),
      C("'I like my job.' → He said he ___ his job.", ["liked", "likes", "like"], "liked", "Like → liked.", tp="reported-statements"),
      C("'I love my dog.' → She said she loved ___ dog.", ["her", "my", "his"], "her", "My → her.", tp="reported-statements"),
      C("'We are ready.' → They said they ___ ready.", ["were", "are", "was"], "were", "Are → were.", tp="reported-statements"),
      F("'I work in a bank.' → He said he ___ in a bank.", "worked", "Work → worked.", tp="reported-statements"),
      X("She said she is busy.", "She said she was busy.", "Після said — крок назад.", "После said — шаг назад.", tp="reported-statements"),
      X("He said me he was tired.", "He told me he was tired.", "Комусь — told me.", "Кому-то — told me.", acc=["He said he was tired."], tp="say-tell"),
      L("She said she was hungry.", ["She said she was hungry.", "She said she is hungry.", "She said she was angry."], "Was hungry.", "Was hungry.", tp="reported-statements"),
      T("Він сказав, що голодний.", "Он сказал, что голоден.", "He said he was hungry.", "Said + was.", acc=["He said that he was hungry."], tp="reported-statements"),
     ]),
   lesson("Tense changes", "Зсув часів", "Сдвиг времён",
     rule("am / is → was · are → were · do → did · will → would · can → could · have done → had done · did → had done",
          "Кожен час робить крок назад. Також змінюються слова часу й місця: today → that day, tomorrow → the next day, yesterday → the day before, here → there.",
          "Каждое время делает шаг назад. Также меняются слова времени и места: today → that day, tomorrow → the next day, yesterday → the day before, here → there.",
          [("'I will help you.' → He said he would help me.", "«Я тобі допоможу» → Він сказав, що допоможе.", "«Я тебе помогу» → Он сказал, что поможет."),
           ("'I can't come.' → She said she couldn't come.", "«Я не можу прийти» → Вона сказала, що не може прийти.", "«Я не могу прийти» → Она сказала, что не может прийти."),
           ("'I've lost my keys.' → He said he had lost his keys.", "«Я загубив ключі» → Він сказав, що загубив ключі.", "«Я потерял ключи» → Он сказал, что потерял ключи.")]),
     [C("'I will call you.' → He said he ___ call me.", ["would", "will", "can"], "would", "Will → would.", tp="reported-tenses"),
      C("'I can drive.' → She said she ___ drive.", ["could", "can", "would"], "could", "Can → could.", tp="reported-tenses"),
      C("'I'm working.' → He said he ___ working.", ["was", "is", "were"], "was", "Am working → was working.", tp="reported-tenses"),
      C("'I've finished.' → She said she ___ finished.", ["had", "has", "have"], "had", "Have finished → had finished.", tp="reported-tenses"),
      C("'I'll see you tomorrow.' → He said he would see me ___ .", ["the next day", "tomorrow", "yesterday"], "the next day", "Tomorrow → the next day.", tp="reported-tenses"),
      M([("am / is", "was"), ("will", "would"), ("can", "could"), ("have done", "had done")], "Крок назад.", "Шаг назад.", tp="reported-tenses"),
      X("He said he will come.", "He said he would come.", "Will → would.", tp="reported-tenses"),
      X("She said she can't swim.", "She said she couldn't swim.", "Can't → couldn't.", tp="reported-tenses"),
      T("Вона сказала, що подзвонить завтра.", "Она сказала, что позвонит завтра.", "She said she would call the next day.", "Will → would.", acc=["She said she would call tomorrow.", "She said that she would call the next day.", "She said she'd call the next day.", "She said she'd call tomorrow."], tp="reported-tenses"),
     ]),
   lesson("say or tell", "say чи tell", "say или tell",
     rule(("say (something) · say to someone · tell SOMEONE (something)", "say (something) · say to someone · tell SOMEONE (something)"),
          "Tell — обов'язково з тим, кому: She told me… He told us… Say — без «кому» (або say to me). Не можна: said me, told that.",
          "Tell — обязательно с тем, кому: She told me… He told us… Say — без «кому» (или say to me). Нельзя: said me, told that.",
          [("She said she was late.", "Вона сказала, що запізнюється.", "Она сказала, что опаздывает."),
           ("She told me she was late.", "Вона сказала мені, що запізнюється.", "Она сказала мне, что опаздывает."),
           ("He told us a funny story.", "Він розповів нам смішну історію.", "Он рассказал нам смешную историю.")]),
     [C("He ___ me he was tired.", ["told", "said", "say"], "told", "Комусь → told me.", "Кому-то → told me.", tp="say-tell"),
      C("She ___ she didn't know.", ["said", "told", "tell"], "said", "Без «кому» → said.", "Без «кому» → said.", tp="say-tell"),
      C("Can you ___ me the time?", ["tell", "say", "speak"], "tell", "Tell me.", tp="say-tell"),
      C("He ___ 'hello' to everyone.", ["said", "told", "talked"], "said", "Say hello.", tp="say-tell"),
      C("Grandma ___ us a story.", ["told", "said", "spoke"], "told", "Tell a story.", tp="say-tell"),
      W(["said", "told"], ["She ___ me the truth.", "He ___ he was sorry.", "They ___ us about the trip.", "I ___ goodbye."], ["told", "said", "told", "said"], "Tell + кому; say — без «кому».", "Tell + кому; say — без «кому».", tp="say-tell"),
      X("She said me that she was ill.", "She told me that she was ill.", "Told me.", acc=["She said that she was ill.", "She told me she was ill."], tp="say-tell"),
      X("He told that he was busy.", "He said that he was busy.", "Без «кому» → said.", acc=["He said he was busy.", "He told me that he was busy."], tp="say-tell"),
      T("Він сказав мені правду.", "Он сказал мне правду.", "He told me the truth.", "Tell the truth.", tp="say-tell"),
     ]),
  ],
  [C("'I'm happy.' → She said she ___ happy.", ["was", "is", "were"], "was", "Is → was.", tp="reported-statements"),
   C("'I will help.' → He said he ___ help.", ["would", "will", "can"], "would", "Will → would.", tp="reported-tenses"),
   C("'I can't come.' → She said she ___ come.", ["couldn't", "can't", "wouldn't"], "couldn't", "Can't → couldn't.", tp="reported-tenses"),
   C("He ___ me he was sorry.", ["told", "said", "say"], "told", "Told me.", tp="say-tell"),
   C("She ___ she was leaving.", ["said", "told", "tell"], "said", "Said.", tp="say-tell"),
   F("'I've lost my phone.' → He said he ___ lost his phone.", "had", "Have → had.", tp="reported-tenses"),
   F("'I love my job.' → She said she loved ___ job.", "her", "My → her.", tp="reported-statements"),
   X("He said me he was busy.", "He told me he was busy.", "Told me.", acc=["He said he was busy."], tp="say-tell"),
   X("She said she will call.", "She said she would call.", "Will → would.", acc=["She said she'd call."], tp="reported-tenses"),
   B("She told me she was tired", "She told me → she was tired.", tp="say-tell"),
   T("Вони сказали, що живуть у Львові.", "Они сказали, что живут во Львове.", "They said they lived in Lviv.", "Live → lived.", acc=["They said that they lived in Lviv."], tp="reported-statements"),
   L("He told us a funny story.", ["He told us a funny story.", "He said us a funny story.", "He told us a funny stone."], "Told us.", "Told us.", tp="say-tell"),
  ], "reported-speech"))

# ============ 15. Относительные придаточные ============
UNITS.append(unit(15, "grammar", "Relative clauses", "Підрядні означальні", "Относительные придаточные",
  rule(("who — люди · which — речі · that — і те, й те · where — місце · whose — чий", "who — люди · which — вещи · that — и то, и другое · where — место · whose — чей"),
       "Підрядне означальне пояснює, про кого чи про що йдеться: The woman who lives next door is a doctor. The phone which I bought is great.",
       "Определительное придаточное поясняет, о ком или о чём речь: The woman who lives next door is a doctor. The phone which I bought is great.",
       [("She's the girl who won the prize.", "Це та дівчина, яка виграла приз.", "Это та девушка, которая выиграла приз."),
        ("This is the café where we met.", "Це кафе, де ми познайомилися.", "Это кафе, где мы познакомились."),
        ("He's the man whose car was stolen.", "Це той чоловік, чию машину вкрали.", "Это тот мужчина, чью машину украли.")]),
  [V("who", "/huː/", "який, котрий (про людей)", "который (о людях)", "the man who called"),
   V("which", "/wɪtʃ/", "який, котрий (про речі)", "который (о вещах)", "the book which I read"),
   V("that", "/ðæt/", "який (про людей і речі)", "который (о людях и вещах)", "the film that we saw"),
   V("where", "/weə/", "де (про місце)", "где (о месте)", "the town where I was born"),
   V("whose", "/huːz/", "чий", "чей", "the girl whose dog bit me"),
   V("neighbour", "/ˈneɪbə/", "сусід", "сосед", "the neighbour who helped us"),
   V("prize", "/praɪz/", "приз, премія", "приз, премия", "She won a prize."),
   V("recommend", "/ˌrekəˈmend/", "рекомендувати", "рекомендовать", "the hotel you recommended"),
   V("hometown", "/ˈhəʊmtaʊn/", "рідне місто", "родной город", "This is my hometown."),
   V("tool", "/tuːl/", "інструмент", "инструмент", "a tool which cuts wood")],
  [
   lesson("who, which, that", "who, which, that", "who, which, that",
     rule(("людина + who / that · річ + which / that", "человек + who / that · вещь + which / that"),
          "Who — про людей, which — про речі й тварин, that — для обох (у розмові частіше). The man who / that lives here. The car which / that I bought.",
          "Who — о людях, which — о вещах и животных, that — для обоих (в разговоре чаще). The man who / that lives here. The car which / that I bought.",
          [("The woman who lives next door is a nurse.", "Жінка, яка живе поруч, — медсестра.", "Женщина, которая живёт рядом, — медсестра."),
           ("I lost the ring which you gave me.", "Я загубила каблучку, яку ти мені подарував.", "Я потеряла кольцо, которое ты мне подарил."),
           ("It's a film that everyone loves.", "Це фільм, який усі люблять.", "Это фильм, который все любят.")]),
     [C("The man ___ called you is my boss.", ["who", "which", "where"], "who", "Людина → who.", "Человек → who.", tp="relative-who-which"),
      C("The book ___ I'm reading is great.", ["which", "who", "where"], "which", "Річ → which.", "Вещь → which.", tp="relative-who-which"),
      C("A vet is a person ___ treats animals.", ["who", "which", "whose"], "who", "Person → who.", tp="relative-who-which"),
      C("A fridge is a machine ___ keeps food cold.", ["which", "who", "where"], "which", "Machine → which.", tp="relative-who-which"),
      C("The dog ___ lives next door is very noisy.", ["that", "who", "where"], "that", "Тварина → which / that.", "Животное → which / that.", tp="relative-who-which"),
      M([("A teacher is a person", "who teaches."), ("A charger is a thing", "which charges your phone."), ("A pilot is someone", "who flies planes."), ("Scissors are a tool", "which cuts paper.")], "Визначення.", "Определения.", tp="relative-who-which"),
      X("The girl which sings is my sister.", "The girl who sings is my sister.", "Людина → who.", "Человек → who.", acc=["The girl that sings is my sister."], tp="relative-who-which"),
      X("The phone who I bought is broken.", "The phone which I bought is broken.", "Річ → which.", "Вещь → which.", acc=["The phone that I bought is broken.", "The phone I bought is broken."], tp="relative-who-which"),
      T("Жінка, яка живе поруч, — лікарка.", "Женщина, которая живёт рядом, — врач.", "The woman who lives next door is a doctor.", "Who.", acc=["The woman that lives next door is a doctor."], tp="relative-who-which"),
     ]),
   lesson("where, whose", "where, whose", "where, whose",
     rule(("місце + where · чий + whose", "место + where · чей + whose"),
          "Where — про місце: the house where I grew up. Whose — замість his / her / their: the man whose wife is a singer (= his wife is a singer).",
          "Where — о месте: the house where I grew up. Whose — вместо his / her / their: the man whose wife is a singer (= his wife is a singer).",
          [("This is the hospital where I was born.", "Це лікарня, де я народився.", "Это больница, где я родился."),
           ("That's the girl whose brother is famous.", "Це дівчина, чий брат відомий.", "Это девушка, чей брат знаменит."),
           ("Is there a shop where I can buy a charger?", "Тут є магазин, де можна купити зарядку?", "Здесь есть магазин, где можно купить зарядку?")]),
     [C("This is the café ___ we first met.", ["where", "which", "who"], "where", "Місце → where.", "Место → where.", tp="relative-where-whose"),
      C("He's the man ___ car was stolen.", ["whose", "who", "which"], "whose", "Чия машина → whose.", "Чья машина → whose.", tp="relative-where-whose"),
      C("Lviv is the city ___ my parents live.", ["where", "which", "whose"], "where", "Where.", tp="relative-where-whose"),
      C("I have a friend ___ dad is a pilot.", ["whose", "who", "who's"], "whose", "Whose.", tp="relative-where-whose"),
      W(["who", "which", "where", "whose"], ["The woman ___ cut my hair was great.", "The salon ___ she works is in the centre.", "The salon ___ owner is French is expensive.", "I bought a shampoo ___ smells nice."], ["who", "where", "whose", "which"],
        "Людина / місце / чий / річ.", "Человек / место / чей / вещь.", reuse=False, tp="relative-clauses"),
      X("This is the town which I grew up.", "This is the town where I grew up.", "Місце + where.", "Место + where.", acc=["This is the town that I grew up in.", "This is the town which I grew up in."], tp="relative-where-whose"),
      X("That's the boy who's bike is red.", "That's the boy whose bike is red.", "Чий — whose.", "Чей — whose.", tp="relative-where-whose"),
      L("This is the house where I was born.", ["This is the house where I was born.", "This is the house which I was born.", "This is the horse where I was born."], "Where.", "Where.", tp="relative-where-whose"),
      T("Це ресторан, де ми святкували весілля.", "Это ресторан, где мы праздновали свадьбу.", "This is the restaurant where we celebrated our wedding.", "Where.", acc=["This is the restaurant where we had our wedding."], tp="relative-where-whose"),
     ]),
   lesson("Leaving out who / which / that", "Коли можна пропустити", "Когда можно опустить",
     rule(("пропускаємо, якщо після нього є інший підмет: the book (that) I read", "опускаем, если после него есть другое подлежащее: the book (that) I read"),
          "The film (that) we saw was great — можна пропустити (після that йде we). The man who lives here — не можна (після who одразу дієслово).",
          "The film (that) we saw was great — можно опустить (после that идёт we). The man who lives here — нельзя (после who сразу глагол).",
          [("The cake (that) you made is delicious.", "Торт, який ти спекла, — смачнющий.", "Торт, который ты испекла, — очень вкусный."),
           ("Is this the hotel (which) you recommended?", "Це той готель, який ти радив?", "Это тот отель, который ты советовал?"),
           ("The woman who called you is here. (не можна пропустити)", "Жінка, яка тобі дзвонила, тут.", "Женщина, которая тебе звонила, здесь.")]),
     [C("Can we leave out the word? → The jacket that I bought was cheap.", ["Yes", "No"], "Yes", "Після that іде I → можна.", "После that идёт I → можно.", tp="relative-omission"),
      C("Can we leave out the word? → The man who lives here is a doctor.", ["No", "Yes"], "No", "Після who одразу дієслово → не можна.", "После who сразу глагол → нельзя.", tp="relative-omission"),
      C("Can we leave out the word? → The film which we watched was long.", ["Yes", "No"], "Yes", "Після which іде we → можна.", "После which идёт we → можно.", tp="relative-omission"),
      C("Can we leave out the word? → The bus that goes to the airport is late.", ["No", "Yes"], "No", "Після that одразу дієслово.", "После that сразу глагол.", tp="relative-omission"),
      B("The present you gave me is beautiful", "The present (that) you gave me → is beautiful.", tp="relative-omission"),
      R([("tf", "Lena's flat is in the street where she grew up.", True), ("tf", "The landlord who owns the flat lives in Poland.", False), ("c", "What did her neighbour give her?", ["a plant", "a key", "a cake"], "a plant")],
        "Flat in her childhood street; landlord lives downstairs; neighbour gave a plant.",
        text="I've just moved into a flat which is in the street where I grew up. The landlord, who lives downstairs, is very kind. My neighbour, whose daughter goes to my old school, gave me a plant. It's the best present that anyone has given me this year!"),
      X("The man lives next door is a pilot.", "The man who lives next door is a pilot.", "Тут who пропустити не можна.", "Здесь who опустить нельзя.", acc=["The man that lives next door is a pilot."], tp="relative-omission"),
      L("Is this the hotel you recommended?", ["Is this the hotel you recommended?", "Is this the hotel where you recommended?", "Is this the hostel you recommended?"], "Hotel (that) you recommended.", "Hotel (that) you recommended.", tp="relative-omission"),
      T("Фільм, який ми дивилися вчора, був чудовий.", "Фильм, который мы смотрели вчера, был отличный.", "The film we watched yesterday was great.", "Можна без that.", "Можно без that.", acc=["The film that we watched yesterday was great.", "The film which we watched yesterday was great.", "The movie we watched yesterday was great."], tp="relative-omission"),
     ]),
  ],
  [C("The woman ___ teaches us is from London.", ["who", "which", "where"], "who", "Who.", tp="relative-who-which"),
   C("This is the phone ___ I bought.", ["which", "who", "where"], "which", "Which.", tp="relative-who-which"),
   C("This is the school ___ I studied.", ["where", "which", "whose"], "where", "Where.", tp="relative-where-whose"),
   C("She's the girl ___ mum is a singer.", ["whose", "who", "who's"], "whose", "Whose.", tp="relative-where-whose"),
   C("Can we leave out 'that'? The cake that she made was great.", ["Yes", "No"], "Yes", "Можна.", "Можно.", tp="relative-omission"),
   F("A pilot is a person ___ flies planes.", "who", "Who.", acc=["that"], tp="relative-who-which"),
   F("A kettle is a thing ___ boils water.", "which", "Which.", acc=["that"], tp="relative-who-which"),
   X("The man which helped me was kind.", "The man who helped me was kind.", "Who.", acc=["The man that helped me was kind."], tp="relative-who-which"),
   X("This is the city which I was born.", "This is the city where I was born.", "Where.", acc=["This is the city that I was born in."], tp="relative-where-whose"),
   B("I have a friend whose dad is a pilot", "A friend → whose dad is a pilot.", tp="relative-where-whose"),
   T("Це кафе, де ми познайомилися.", "Это кафе, где мы познакомились.", "This is the café where we met.", "Where.", acc=["This is the cafe where we met.", "That's the café where we met."], tp="relative-where-whose"),
   L("The book that you gave me is great.", ["The book that you gave me is great.", "The book who you gave me is great.", "The book that you gave me was great."], "That.", "That.", tp="relative-who-which"),
  ], "relative-clauses"))
